// Build the header row + string matrix. The workflow now OWNS the schema:
// it writes exactly the columns it can fill, so headers come from the query.
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => Object.keys(r).length > 0);

const toText = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

if (rows.length === 0) {
  return [{ json: { row_count: 0, column_count: 0, columns: [], records: [], snapshot_date: '' } }];
}

const columns = [];
for (const r of rows) for (const k of Object.keys(r)) if (!columns.includes(k)) columns.push(k);

const seen = new Set();
const records = [];
const teams = new Set();
const managers = new Set();
for (const r of rows) {
  const id = toText(r['Employee ID']);
  if (id !== '' && seen.has(id)) continue;
  seen.add(id);
  records.push(columns.map((c) => toText(r[c])));
  if (toText(r['Team']) !== '') teams.add(toText(r['Team']));
  if (toText(r["Manager's Name"]) !== '') managers.add(toText(r["Manager's Name"]));
}

return [{ json: {
  row_count: records.length,
  column_count: columns.length,
  columns,
  records,
  teams_present: [...teams].sort(),
  manager_count: managers.size,
  snapshot_date: toText(rows[0]['Snapshot Date']),
} }];

// Report which columns are actually populated, so dead ones get named.
const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length > 0);
const L = [];
L.push('FRONTLINE ROSTER REFRESH ABORTED - the query returned zero rows.');
L.push('The Google Sheet was NOT cleared. Its previous contents are intact.');
L.push('');

if (rows.length === 0) {
  L.push('DIAGNOSIS: not even the profiling query returned a row, so the newest');
  L.push("Frontline 'Day' snapshot in the last 30 days is empty.");
  L.push('Check that the upstream pipeline is still loading this table.');
} else {
  const r = rows[0];
  const total = Number(r.total_rows || 0);
  L.push(`Non-NULL value counts on the newest Frontline 'Day' snapshot (${total} rows).`);
  L.push('COUNT ignores NULLs, so 0 means the column is entirely empty.');
  L.push('');
  const dead = [];
  const live = [];
  for (const [k, v] of Object.entries(r)) {
    if (k === 'total_rows') continue;
    const n = Number(v || 0);
    L.push(`  ${n === 0 ? 'DEAD  ' : 'ok    '} ${k} = ${n}`);
    (n === 0 ? dead : live).push(k);
  }
  L.push('');
  const keys = ['emid', 'emailaddress', 'username', 'employee'];
  const usable = keys.filter((k) => live.includes(k));
  if (total === 0) {
    L.push('DIAGNOSIS: the snapshot itself has no Frontline rows.');
  } else if (usable.length === 0) {
    L.push('DIAGNOSIS: every candidate identity column (emid, emailaddress, username,');
    L.push('employee) is NULL, so no per-employee key can be built from this table.');
    L.push('It cannot produce an agent-level roster. A different source is required.');
    L.push('Send this list back and it can be repointed.');
  } else {
    L.push(`DIAGNOSIS: usable identity columns exist (${usable.join(', ')}), so the`);
    L.push('employee key is not the blocker. Remaining suspects are the snapshot-date');
    L.push('match or the QUALIFY dedupe.');
  }
  if (dead.length) {
    L.push('');
    L.push(`Columns to drop from the sheet, all empty: ${dead.join(', ')}`);
  }
}
return [{ json: { diagnosis: L.join('\n') } }];

// One values:batchUpdate body per chunk. Header row is row 1 of the payload.
const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;

const source = $('Code - Normalize Roster').first().json;
const allRows = [source.columns || [], ...(source.records || [])];
const chunks = [];

for (let offset = 0; offset < allRows.length; offset += CHUNK_ROWS) {
  const slice = allRows.slice(offset, offset + CHUNK_ROWS);
  const startRow = offset + 1;
  chunks.push({
    chunk_index: chunks.length + 1,
    chunk_rows: slice.length,
    start_row: startRow,
    request_body: {
      valueInputOption: 'RAW',
      data: [{ range: `${TAB_NAME}!A${startRow}`, majorDimension: 'ROWS', values: slice }],
    },
  });
}
return chunks.map((c) => ({ json: { ...c, chunk_total: chunks.length } }));
